# Улучшенная структура БД для хранения песен

Предлагаю нормализованную структуру, которая учитывает возможные повторения названий и текстов:

```sql
-- Таблица уникальных текстов песен
CREATE TABLE lyrics (
    id SERIAL PRIMARY KEY,
    text TEXT NOT NULL,
    text_hash VARCHAR(64) UNIQUE NOT NULL, -- для быстрого поиска дубликатов
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Индекс для поиска по хешу
CREATE INDEX idx_lyrics_hash ON lyrics(text_hash);

-- Таблица названий песен
CREATE TABLE song_names (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Индекс для поиска по названию
CREATE INDEX idx_song_names_name ON song_names(name);

-- Основная таблица песен (связывает название, текст и метаданные)
CREATE TABLE songs (
    id SERIAL PRIMARY KEY,
    song_name_id INTEGER NOT NULL REFERENCES song_names(id) ON DELETE RESTRICT,
    lyrics_id INTEGER NOT NULL REFERENCES lyrics(id) ON DELETE RESTRICT,
    link VARCHAR(255) NOT NULL,
    creation_date TIMESTAMP NOT NULL,
    performance_date TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT unique_song_combination UNIQUE (song_name_id, lyrics_id, performance_date)
);

-- Индексы для оптимизации запросов
CREATE INDEX idx_songs_name_id ON songs(song_name_id);
CREATE INDEX idx_songs_lyrics_id ON songs(lyrics_id);
CREATE INDEX idx_songs_performance_date ON songs(performance_date);
CREATE INDEX idx_songs_creation_date ON songs(creation_date);

-- Таблица для связи многие-ко-многим (если одна песня может иметь несколько названий)
CREATE TABLE song_name_variations (
    id SERIAL PRIMARY KEY,
    song_id INTEGER NOT NULL REFERENCES songs(id) ON DELETE CASCADE,
    song_name_id INTEGER NOT NULL REFERENCES song_names(id) ON DELETE CASCADE,
    is_primary BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT unique_song_name_variation UNIQUE (song_id, song_name_id)
);

CREATE INDEX idx_song_name_variations_song ON song_name_variations(song_id);
CREATE INDEX idx_song_name_variations_name ON song_name_variations(song_name_id);
```

## Функции-хелперы для работы с данными

```sql
-- Функция для вычисления хеша текста
CREATE OR REPLACE FUNCTION get_lyrics_hash(lyrics_text TEXT)
RETURNS VARCHAR(64) AS $$
BEGIN
    RETURN encode(digest(lyrics_text, 'sha256'), 'hex');
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Функция для добавления или получения существующего текста
CREATE OR REPLACE FUNCTION get_or_create_lyrics(lyrics_text TEXT)
RETURNS INTEGER AS $$
DECLARE
    lyrics_hash VARCHAR(64);
    lyrics_record_id INTEGER;
BEGIN
    lyrics_hash := get_lyrics_hash(lyrics_text);

    SELECT id INTO lyrics_record_id 
    FROM lyrics 
    WHERE text_hash = lyrics_hash;

    IF lyrics_record_id IS NULL THEN
        INSERT INTO lyrics (text, text_hash)
        VALUES (lyrics_text, lyrics_hash)
        RETURNING id INTO lyrics_record_id;
    END IF;

    RETURN lyrics_record_id;
END;
$$ LANGUAGE plpgsql;

-- Функция для добавления или получения существующего названия
CREATE OR REPLACE FUNCTION get_or_create_song_name(song_name VARCHAR(255))
RETURNS INTEGER AS $$
DECLARE
    name_id INTEGER;
BEGIN
    SELECT id INTO name_id 
    FROM song_names 
    WHERE name = song_name;

    IF name_id IS NULL THEN
        INSERT INTO song_names (name)
        VALUES (song_name)
        RETURNING id INTO name_id;
    END IF;

    RETURN name_id;
END;
$$ LANGUAGE plpgsql;

-- Триггер для обновления updated_at
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_songs_updated_at 
    BEFORE UPDATE ON songs
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();
```

## Примеры использования

```sql
-- Добавление новой песни
DO $$
DECLARE
    v_name_id INTEGER;
    v_lyrics_id INTEGER;
BEGIN
    v_name_id := get_or_create_song_name('Imagine');
    v_lyrics_id := get_or_create_lyrics('Imagine there''s no heaven...');

    INSERT INTO songs (song_name_id, lyrics_id, link, creation_date, performance_date)
    VALUES (v_name_id, v_lyrics_id, 'https://example.com/song1', 
            '2024-01-01', '2024-06-01');
END $$;

-- Поиск всех песен с одинаковым названием
SELECT s.id, sn.name, l.text, s.link, s.performance_date
FROM songs s
JOIN song_names sn ON s.song_name_id = sn.id
JOIN lyrics l ON s.lyrics_id = l.id
WHERE sn.name = 'Imagine';

-- Поиск всех песен с одинаковым текстом
SELECT s.id, sn.name, s.link, s.performance_date
FROM songs s
JOIN song_names sn ON s.song_name_id = sn.id
WHERE s.lyrics_id = (
    SELECT id FROM lyrics WHERE text_hash = get_lyrics_hash('искомый текст')
);

-- Статистика по повторяющимся названиям
SELECT sn.name, COUNT(*) as usage_count
FROM songs s
JOIN song_names sn ON s.song_name_id = sn.id
GROUP BY sn.name
HAVING COUNT(*) > 1
ORDER BY usage_count DESC;
```

## Преимущества такой структуры:

1. **Нормализация** - тексты и названия хранятся однократно
2. **Экономия места** - дедупликация данных
3. **Целостность** - внешние ключи гарантируют связность
4. **Производительность** - индексы ускоряют поиск
5. **Гибкость** - легко добавить дополнительные связи (авторы, исполнители и т.д.)

